WITH valid AS (SELECT *, LEAST(pressure, temp_c) AS least_pressure_temp_c FROM device_readings WHERE reading_ts >= TIMESTAMP '2025-09-01 01:00:00'), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM valid), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT device_code, DATE_TRUNC('DAY', reading_ts) AS activity_day, session_id, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, PERCENTILE_APPROX(temp_c, 0.5) AS temp_c_p50, COUNT(*) FILTER (WHERE device_code = 'DV-02') AS dv_02_rows, GROUPING(device_code) AS grouping_id FROM sessionized GROUP BY ROLLUP (device_code, DATE_TRUNC('DAY', reading_ts), session_id) HAVING dv_02_rows > 1 ORDER BY temp_c_p50 DESC NULLS LAST
